    Game Installed(PortEntry entry){return games.LastOrDefault(g=>g.Repository==entry.Identity&&UpdateManager.Managed(g));}
    bool HasUpdate(PortEntry entry){PortRelease found;Game installed;return available.TryGetValue(entry.Identity,out found)&&!found.FromCache&&(installed=Installed(entry))!=null&&UpdateManager.Available(installed,found);}
    string Subtitle(PortEntry entry){PortRelease found;Game installed;if(available.TryGetValue(entry.Identity,out found)&&!found.FromCache&&(installed=Installed(entry))!=null&&UpdateManager.Available(installed,found))return entry.Platform+" · Atualização disponível";return entry.Platform+" · "+(entry.ManualPackage?"ZIP do site oficial":entry.ProjectOnly?"Sem pacote integrado":entry.PackageKind=="Installer"?"Assistente do autor":entry.AllowPrerelease?"Beta / recompilação":entry.Kind);}
