        if(!closed){foreach(var item in list.Items.Cast<ListBoxItem>()){var entry=(PortEntry)item.Tag;PortRelease found;if(available.TryGetValue(entry.Identity,out found)&&!found.FromCache&&Installed(entry)!=null&&UpdateManager.Available(Installed(entry),found))((TextBlock)((StackPanel)item.Content).Children[1]).Text=entry.Platform+" · Atualização disponível";}
          if(!busy&&installationMode.SelectedIndex==3)FilterEntries();PortRelease current;if(!busy&&selected!=null&&available.TryGetValue(selected.Identity,out current))PresentRelease(selected,current);if(!busy)status.Text=count+" atualização(ões) disponível(is)."+(failed>0?" Não foi possível confirmar "+failed+" fonte(s); tente novamente mais tarde.":"");}
