      if(installed!=null){version.Text+="\nInstalado: "+installed.InstalledVersion;status.Text=!UpdateManager.Available(installed,found)?"Esta versão já está instalada.":found.FromCache?"Confirme a versão atual no GitHub usando Verificar atualização.":entry.PackageKind=="Installer"?"Atualizar abre o assistente do autor. Ele controla a atualização dos arquivos; conclua-o antes de selecionar o aplicativo.":"Atualizar preserva seus arquivos e cria uma cópia completa da versão anterior. Feche o jogo e reserve espaço para essa cópia.";}
