      try{platform.SelectedItem=entry.Platform;list.SelectedItem=list.Items.Cast<ListBoxItem>().First(i=>((PortEntry)i.Tag).Id==entry.Id);PrepareSelection(entry);var sample=PortCatalog.BundledRelease(entry);sample.FromCache=false;sample.Version="v2.0.0";PresentRelease(entry,sample);if(!download.IsEnabled||(string)download.Content!="Atualizar")throw new Exception("New online release must expose Update");sample.FromCache=true;PresentRelease(entry,sample);if((string)download.Content!="Verificar atualização")throw new Exception("Cached release must require online refresh");sample.FromCache=false;sample.Version="v1.0.0";PresentRelease(entry,sample);if(download.IsEnabled)throw new Exception("Same version cannot update");sample.Version="v0.9.0";PresentRelease(entry,sample);if(download.IsEnabled)throw new Exception("Older version cannot update");sample.Version="v2.0.0";PresentRelease(entry,sample);installationMode.SelectedIndex=3;if(list.Items.Count!=1||((PortEntry)((ListBoxItem)list.Items[0]).Tag).Id!=entry.Id)throw new Exception("Updates filter must show only installed newer online releases");list.SelectedIndex=0;PrepareSelection(entry);PresentRelease(entry,sample);Height=900;Launcher.CaptureWindow(this,path);}
      finally{games.Remove(previous);if(root.StartsWith(parent+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(root).StartsWith(".ui-update-fixture-"))Directory.Delete(root,true);}
    }
  }
